8|// A simple dense matrix stored in row-major order.
9|//
10|// Row-major means element (r, c) lives at index (r * cols + c). Iterating
11|// row by row touches contiguous memory and is friendly to CPU caches.
12|class Matrix {
13|public:
14|    Matrix(std::size_t rows, std::size_t cols);
15|
16|    std::size_t rows() const { return rows_; }
17|    std::size_t cols() const { return cols_; }
18|    std::size_t size() const { return data_.size(); }
19|
20|    // Element access.
21|    double&       at(std::size_t r, std::size_t c)       { return data_[r * cols_ + c]; }
22|    const double& at(std::size_t r, std::size_t c) const { return data_[r * cols_ + c]; }
23|
24|    // Computes the sum of all elements.
25|    double SumAll() const;
26|
27|    // Computes the per-row sum of all elements. The result vector has
28|    // length rows(). result[r] = sum of row r.
29|    std::vector<double> SumPerRow() const;
